/* Generated by scripts/gen_coop_dispatch.py: the co-op bridge's calls, each handed to the build of the loaded cart
 * (English or French Emerald: its game code's last letter, ROM 0x080000AF). GPL-3.0, see NOTICE. */
#include "pk_coop.h"
#include "pk_coop_after.h"
#include "pk_coop_field.h"
#include "pk_coop_lock.h"
#include <mgba/core/core.h>

static int coopFrench; /* the last cart seen: the calls with no core go to it */

int pk_coop_french(struct mCore* core) {
    if (core)
        coopFrench = core->busRead8(core, 0x080000AF) == 'F' && core->busRead8(core, 0x080000AC) == 'B';
    return coopFrench;
}

