int pk_coopfr_add_money(struct mCore* core, int amount);
int pk_coop_add_money(struct mCore* core, int amount) {
    return pk_coop_french(core) ? pk_coopfr_add_money(core, amount) : pk_coopen_add_money(core, amount);
}

